customer_metrics = Broker.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_period=DATETIME('now', 'start of month', '-6 months')
).Customers.WHERE(
    (join_date >= start_of_period) & (join_date < start_of_current_month)
).CALCULATE(
    signup_month=JOIN_STRINGS('-', YEAR(join_date), LPAD(MONTH(join_date), 2, '0'))
).PARTITION(
    name='monthly_groups', by=signup_month
).CALCULATE(
    month=signup_month,
    PMCS=COUNT(Customers),
    PMAT=AVG(Customers.transactions_made.amount)
)

result = Customers.WHERE(
    HAS(transactions_made) == 1
).CALCULATE(
    customer_id=_id,
    join_date=join_date,
    first_transaction_date=MIN(transactions_made.date_time)
).CALCULATE(
    _id=customer_id,
    time_to_first_transaction=DATEDIFF("days", join_date, first_transaction_date)
)

total_sales_count = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, 'now') < 7))
)

shortest_employment_salesperson = Salespersons.WHERE(
    PRESENT(termination_date)
).CALCULATE(
    days_employed=DATEDIFF("days", hire_date, termination_date)
).TOP_K(
    1, by=days_employed.ASC()
).CALCULATE(
    salesperson_name=JOIN_STRINGS(" ", first_name, last_name),
    phone_number=phone,
    days_employed=days_employed
)

result = DermTreatment.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_12_months_ago=DATETIME('now', 'start of month', '-12 months')
).Treatments.WHERE(
    (start_dt >= start_of_12_months_ago) & (start_dt < start_of_current_month)
).CALCULATE(
    treatment_month=DATETIME(start_dt, 'start of month')
).PARTITION(name="monthly_groups", by=(treatment_month)).CALCULATE(
    month=treatment_month,
    PMTC=COUNT(Treatments),
    PMPD=NDISTINCT(Treatments.CALCULATE(patient_diag_key=JOIN_STRINGS('-', patient_id, diag_id)).patient_diag_key)
).ORDER_BY(month.ASC())

npi_by_year = DermTreatment.Patients.CALCULATE(
    first_treatment_year=YEAR(MIN(treatments_received.start_dt))
).PARTITION(
    name="yearly_groups", by=first_treatment_year
).CALCULATE(
    year=first_treatment_year,
    num_new_patients=COUNT(Patients)
).ORDER_BY(year.ASC()).CALCULATE(
    year=year,
    num_new_patients=num_new_patients,
    NPINPI=num_new_patients - PREV(num_new_patients, by=year.ASC(), default=0)
)

result = Merchants.CALCULATE(
    merchant_name=name,
    cpur=NDISTINCT(
        transactions_received.WHERE(
            LOWER(status) == LOWER("successful")
        ).WHERE(
            PRESENT(coupon_id)
        ).coupon_id
    ) / NDISTINCT(
        transactions_received.WHERE(
            LOWER(status) == LOWER("successful")
        ).txid
    )
)

result = Ewallet.CALCULATE(
    num_transactions=COUNT(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        )
    ),
    total_amount=SUM(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        ).amount
    )
)

user_session_durations = Users.CALCULATE(
    user_id=uid,
    total_duration=ROUND(SUM(
        sessions.WHERE(
            (session_start_ts >= '2023-06-01') & (session_start_ts < '2023-06-08')
        ).CALCULATE(
            duration_in_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_in_seconds
    ), 0)
).WHERE(
    total_duration > 0
).ORDER_BY(
    total_duration.DESC()
)

result = Users.WHERE(
    HASNOT(
        notifications.WHERE(
            DATEDIFF("days", user.created_at, created_at) <= 365
        )
    ) == 1
).CALCULATE(
    user_name=username,
    user_email=email,
    signup_date=created_at
)
